import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));

// Emit one self-contained .mjs holding the whole runtime and the program.
//
// This is honest about what it is. It is not a native binary, and "compiles to
// a universal binary that runs everywhere natively" is not a thing anyone does
// -- universal binaries are per-target builds in a wrapper. What this produces
// is one file with no dependencies and no install, which runs anywhere Node
// runs. That is the achievable version of the idea.
//
// Each module becomes an IIFE returning its exports, so module-local names
// cannot collide no matter how many files define a helper called `nf`.

const IMPORT_RE = /import\s+([\s\S]*?)\s+from\s+(['"])([^'"]+)\2\s*;?/g;

function parseModule(file) {
  const source = fs.readFileSync(file, 'utf8');
  const relativeDeps = [];
  const nodeImports = [];

  const body = source.replace(IMPORT_RE, (match, clause, _q, specifier) => {
    if (specifier.startsWith('node:')) {
      nodeImports.push({ clause: clause.trim(), specifier });
      return '';
    }
    if (!specifier.startsWith('.')) {
      throw new Error(`${path.basename(file)} imports '${specifier}', which is not bundleable`);
    }
    const dep = path.basename(specifier);
    relativeDeps.push(dep);
    const named = clause.trim();
    // Every relative import in this codebase is a named import.
    if (!named.startsWith('{')) {
      throw new Error(`${path.basename(file)} default-imports '${specifier}'; the bundler expects named imports`);
    }
    return `const ${named.replace(/\s+/g, ' ')} = __M[${JSON.stringify(dep)}];`;
  });

  const exported = new Set();
  for (const m of body.matchAll(/export\s+(?:class|function|const|let|var)\s+([A-Za-z_$][\w$]*)/g)) {
    exported.add(m[1]);
  }
  let stripped = body;
  for (const m of body.matchAll(/export\s*\{([^}]*)\}\s*;?/g)) {
    for (const piece of m[1].split(',')) {
      const name = piece.trim().split(/\s+as\s+/).pop().trim();
      if (name) exported.add(name);
    }
    stripped = stripped.replace(m[0], '');
  }
  stripped = stripped.replace(/^\s*export\s+(?=(?:class|function|const|let|var|async)\b)/gm, '');

  return { file, body: stripped, exported: [...exported], relativeDeps, nodeImports };
}

// Depth-first, dependencies before dependents.
function collect(entry, seen = new Map(), order = []) {
  const name = path.basename(entry);
  if (seen.has(name)) return order;
  const mod = parseModule(entry);
  seen.set(name, mod);
  for (const dep of mod.relativeDeps) {
    collect(path.join(HERE, dep), seen, order);
  }
  order.push(mod);
  return order;
}

function hoistNodeImports(modules) {
  const defaults = new Map();     // specifier -> local name
  const named = new Map();        // specifier -> Set(names)
  for (const mod of modules) {
    for (const { clause, specifier } of mod.nodeImports) {
      if (clause.startsWith('{')) {
        const set = named.get(specifier) ?? new Set();
        for (const piece of clause.replace(/[{}]/g, '').split(',')) {
          const n = piece.trim();
          if (n) set.add(n);
        }
        named.set(specifier, set);
      } else {
        defaults.set(specifier, clause);
      }
    }
  }
  const lines = [];
  for (const [specifier, local] of defaults) lines.push(`import ${local} from '${specifier}';`);
  for (const [specifier, names] of named) {
    lines.push(`import { ${[...names].join(', ')} } from '${specifier}';`);
  }
  return lines.join('\n');
}

export function buildBundle(programSource, programName, { seed = 0, caps = [] } = {}) {
  const modules = collect(path.join(HERE, 'interpreter.js'));
  for (const extra of ['prove.js', 'analysis.js']) {
    collect(path.join(HERE, extra), new Map(modules.map((m) => [path.basename(m.file), m])), modules);
  }

  const parts = [
    '// Generated by `sarvm build`. Self-contained: no dependencies, no install.',
    `// Program: ${programName}`,
    hoistNodeImports(modules),
    '',
    'const __M = {};',
  ];

  for (const mod of modules) {
    const key = JSON.stringify(path.basename(mod.file));
    parts.push(`__M[${key}] = (() => {`);
    parts.push(mod.body.trim());
    parts.push(`return { ${mod.exported.join(', ')} };`);
    parts.push('})();');
    parts.push('');
  }

  parts.push('const { Interpreter } = __M["interpreter.js"];');
  parts.push('const { SarvmError } = __M["errors.js"];');
  parts.push(`const __source = ${JSON.stringify(programSource)};`);
  parts.push(`const __seed = ${JSON.stringify(seed)};`);
  parts.push(`const __caps = ${JSON.stringify(caps)};`);
  parts.push(`
const __interp = new Interpreter({ seed: __seed, caps: __caps });
try {
  __interp.run(__source, ${JSON.stringify(programName)});
} catch (e) {
  if (e instanceof SarvmError) {
    console.error(e.format(__source, ${JSON.stringify(programName)}));
    process.exitCode = 1;
  } else {
    throw e;
  }
} finally {
  __interp.devices.shutdown();
}
`.trim());

  return `${parts.join('\n')}\n`;
}
